/**
 * MinStack — O(1) push, pop, top, getMin.
 *
 * Two stacks are kept in parallel:
 *   1. `stack`   – the actual values
 *   2. `minStack` – the running minimum at each depth
 */
function paginate_results() {
  const stack = [];
  const minStack = [];

  return {
    push(val) {
      stack.push(val);
      const currentMin =
        minStack.length === 0
          ? val
          : Math.min(val, minStack[minStack.length - 1]);
      minStack.push(currentMin);
    },

    pop() {
      if (stack.length === 0) throw new Error("Stack is empty");
      minStack.pop();
      return stack.pop();
    },

    top() {
      if (stack.length === 0) throw new Error("Stack is empty");
      return stack[stack.length - 1];
    },

    getMin() {
      if (stack.length === 0) throw new Error("Stack is empty");
      return minStack[minStack.length - 1];
    },

    size() {
      return stack.length;
    },
  };
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(condition, label) {
    if (condition) {
      passed++;
      console.log(`  PASS: ${label}`);
    } else {
      failed++;
      console.error(`  FAIL: ${label}`);
    }
  }

  // --- basic operations ---
  console.log("Basic operations");
  {
    const s = paginate_results();
    s.push(3);
    s.push(5);
    assert(s.getMin() === 3, "min after push 3,5");
    assert(s.top() === 5, "top after push 3,5");
    s.push(2);
    s.push(1);
    assert(s.getMin() === 1, "min after push 2,1");
    assert(s.top() === 1, "top after push 2,1");
    assert(s.pop() === 1, "pop returns 1");
    assert(s.getMin() === 2, "min after pop (1 removed)");
    assert(s.top() === 2, "top after pop");
    assert(s.pop() === 2, "pop returns 2");
    assert(s.getMin() === 3, "min after pop (2 removed)");
    assert(s.pop() === 5, "pop returns 5");
    assert(s.getMin() === 3, "min after pop (5 removed)");
    assert(s.pop() === 3, "pop returns 3");
    assert(s.size() === 0, "empty after all pops");
  }

  // --- duplicates ---
  console.log("\nDuplicate values");
  {
    const s = paginate_results();
    s.push(2);
    s.push(2);
    s.push(2);
    assert(s.getMin() === 2, "min with all 2s");
    s.pop();
    assert(s.getMin() === 2, "min still 2 after one pop");
    s.pop();
    assert(s.getMin() === 2, "min still 2 after two pops");
    s.pop();
    assert(s.size() === 0, "empty after popping all 2s");
  }

  // --- negative / large values ---
  console.log("\nNegative and large values");
  {
    const s = paginate_results();
    s.push(-10);
    s.push(0);
    s.push(Number.MAX_SAFE_INTEGER);
    assert(s.getMin() === -10, "min is -10 with mixed values");
    s.push(-20);
    assert(s.getMin() === -20, "min is -20 after pushing -20");
    s.pop();
    assert(s.getMin() === -10, "min back to -10 after popping -20");
  }

  // --- single element ---
  console.log("\nSingle element");
  {
    const s = paginate_results();
    s.push(42);
    assert(s.top() === 42, "top of single element");
    assert(s.getMin() === 42, "min of single element");
    assert(s.pop() === 42, "pop single element");
    assert(s.size() === 0, "empty after single pop");
  }

  // --- errors on empty stack ---
  console.log("\nEmpty stack errors");
  {
    const s = paginate_results();
    let threw;
    threw = false;
    try { s.pop(); } catch (e) { threw = true; }
    assert(threw, "pop on empty throws");

    threw = false;
    try { s.top(); } catch (e) { threw = true; }
    assert(threw, "top on empty throws");

    threw = false;
    try { s.getMin(); } catch (e) { threw = true; }
    assert(threw, "getMin on empty throws");
  }

  // --- interleaved push/pop verifying min tracks correctly ---
  console.log("\nInterleaved push/pop");
  {
    const s = paginate_results();
    s.push(5);
    s.push(3);
    assert(s.getMin() === 3, "min=3");
    s.push(7);
    assert(s.getMin() === 3, "min still 3 after push 7");
    s.pop(); // remove 7
    assert(s.getMin() === 3, "min still 3 after pop 7");
    s.pop(); // remove 3
    assert(s.getMin() === 5, "min=5 after popping 3");
    s.push(1);
    assert(s.getMin() === 1, "min=1 after push 1");
    s.push(10);
    assert(s.getMin() === 1, "min still 1 after push 10");
    s.pop(); // remove 10
    s.pop(); // remove 1
    assert(s.getMin() === 5, "min back to 5");
    assert(s.size() === 1, "one element left");
  }

  // --- large sequence ---
  console.log("\nLarge sequence (1000 pushes)");
  {
    const s = paginate_results();
    for (let i = 0; i < 1000; i++) s.push(i);
    assert(s.getMin() === 0, "min is 0 after 0..999");
    assert(s.top() === 999, "top is 999");
    for (let i = 999; i >= 0; i--) {
      assert(s.getMin() === 0, `min=0 at depth ${i + 1}`);
      s.pop();
    }
    assert(s.size() === 0, "empty after popping 1000 elements");
  }

  console.log(`\nResults: ${passed} passed, ${failed} failed`);
  if (failed > 0) process.exit(1);
}

runTests();
